      ({io_in_bits_ctrl_fuOpType == 9'hC4, io_in_bits_ctrl_fuOpType == 9'hC0}),
    .io_isFcvtmod (isFcvtmod),
    .io_result    (_fcvt_io_result),
    .io_fflags    (_fcvt_io_fflags)
  );
